/**
 * PluginShare - 插件分享系统
 * 基于 nanobot plugin share 架构
 */
import { toolRegistry } from './registry.js';
import { getFavorites } from './ToolRating.js';

const SHARE_KEY = 'ai-creator-shared-plugins';
const SHARE_SERVER = 'https://api.jsonbin.io/v3/b'; // 免费 JSON 存储

// 获取分享的插件列表
export function getSharedPlugins() {
  const data = localStorage.getItem(SHARE_KEY);
  if (!data) return [];
  
  try {
    const parsed = JSON.parse(data);
    return parsed.plugins || [];
  } catch {
    return [];
  }
}

// 保存分享的插件到本地列表
function saveSharedPlugin(plugin) {
  const all = getSharedPlugins();
  const existing = all.findIndex(p => p.id === plugin.id);
  
  if (existing >= 0) {
    all[existing] = plugin;
  } else {
    all.push(plugin);
  }
  
  localStorage.setItem(SHARE_KEY, JSON.stringify({ plugins: all }));
}

// 导出插件为分享格式
export function exportPlugin(pluginId) {
  const tool = toolRegistry.get(pluginId);
  if (!tool) {
    return { success: false, error: '工具不存在' };
  }
  
  const shareData = {
    id: tool.id,
    name: tool.name,
    icon: tool.icon,
    description: tool.description,
    version: '1.0.0',
    author: 'anonymous',
    config: tool.config || {},
    tools: tool.tools || [],
    tags: tool.tags || [],
    createdAt: Date.now()
  };
  
  const encoded = btoa(unescape(encodeURIComponent(JSON.stringify(shareData))));
  
  return {
    success: true,
    data: shareData,
    encoded,
    url: `${window.location.origin}?plugin=${encoded}`
  };
}

// 从分享数据导入插件
export function importPlugin(shareDataOrEncoded) {
  try {
    let data;
    
    // 如果是 URL 编码格式
    if (typeof shareDataOrEncoded === 'string' && shareDataOrEncoded.length > 100) {
      try {
        data = JSON.parse(decodeURIComponent(escape(atob(shareDataOrEncoded))));
      } catch {
        data = JSON.parse(shareDataOrEncoded);
      }
    } else if (typeof shareDataOrEncoded === 'string') {
      data = JSON.parse(shareDataOrEncoded);
    } else {
      data = shareDataOrEncoded;
    }
    
    // 验证必要字段
    if (!data.id || !data.name) {
      return { success: false, error: '无效的插件数据' };
    }
    
    // 检查是否已存在
    if (toolRegistry.get(data.id)) {
      return { success: false, error: '插件已存在' };
    }
    
    // 注册到工具系统
    toolRegistry.register({
      id: data.id,
      name: data.name,
      icon: data.icon || '🔌',
      description: data.description || '',
      version: data.version,
      author: data.author,
      config: data.config || {},
      tools: data.tools || [],
      tags: data.tags || ['shared']
    });
    
    // 保存到分享列表
    saveSharedPlugin(data);
    
    return { success: true, plugin: data };
  } catch (e) {
    return { success: false, error: '解析失败: ' + e.message };
  }
}

// 生成分享链接（使用 URL 参数）
export function generateShareUrl(pluginId) {
  const result = exportPlugin(pluginId);
  if (!result.success) return null;
  
  // 简化格式: 直接包含 JSON 数据
  const jsonStr = JSON.stringify(result.data);
  const compressed = btoa(unescape(encodeURIComponent(jsonStr)));
  
  return `${window.location.origin}${window.location.pathname}#plugin=${compressed}`;
}

// 从 URL 导入插件
export function importFromUrl() {
  const hash = window.location.hash;
  if (!hash.startsWith('#plugin=')) return null;
  
  const encoded = hash.slice(8);
  return importPlugin(encoded);
}

// 复制到剪贴板
export async function copyToClipboard(text) {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch {
    // 降级方案
    const textarea = document.createElement('textarea');
    textarea.value = text;
    textarea.style.position = 'fixed';
    textarea.style.opacity = '0';
    document.body.appendChild(textarea);
    textarea.select();
    const success = document.execCommand('copy');
    document.body.removeChild(textarea);
    return success;
  }
}

// 导出所有收藏的工具
export function exportFavorites() {
  const favorites = getFavorites();
  const favoriteTools = favorites.map(id => toolRegistry.get(id)).filter(Boolean);
  
  if (favoriteTools.length === 0) {
    return { success: false, error: '没有收藏的工具' };
  }
  
  const exportData = {
    type: 'ai-creator-favorites',
    version: '1.0',
    tools: favoriteTools.map(tool => ({
      id: tool.id,
      name: tool.name,
      icon: tool.icon,
      description: tool.description,
      config: tool.config || {},
      tools: tool.tools || [],
      tags: tool.tags || []
    })),
    exportedAt: Date.now()
  };
  
  return {
    success: true,
    data: exportData,
    encoded: btoa(unescape(encodeURIComponent(JSON.stringify(exportData))))
  };
}

// 导入收藏包
export function importFavorites(packedData) {
  try {
    let data;
    
    if (typeof packedData === 'string') {
      try {
        data = JSON.parse(decodeURIComponent(escape(atob(packedData))));
      } catch {
        data = JSON.parse(packedData);
      }
    } else {
      data = packedData;
    }
    
    if (data.type !== 'ai-creator-favorites') {
      return { success: false, error: '无效的收藏包' };
    }
    
    let imported = 0;
    for (const toolData of data.tools) {
      if (!toolRegistry.get(toolData.id)) {
        toolRegistry.register({
          id: toolData.id,
          name: toolData.name,
          icon: toolData.icon || '⭐',
          description: toolData.description || '',
          config: toolData.config || {},
          tools: toolData.tools || [],
          tags: ['shared', ...(toolData.tags || [])]
        });
        imported++;
      }
    }
    
    return { success: true, count: imported };
  } catch (e) {
    return { success: false, error: '解析失败: ' + e.message };
  }
}